package pe.edu.upeu.notificacion.controller; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import pe.edu.upeu.notificacion.dto.*; import pe.edu.upeu.notificacion.service.NotificacionService; @RestController @RequestMapping("/internal/v1/notificaciones") @RequiredArgsConstructor public class NotificacionInternalController{private final NotificacionService service;@PostMapping public ResponseEntity<NotificacionResponse>crear(@Valid @RequestBody NotificacionRequest r){return ResponseEntity.status(201).body(service.crear(r));}}